#!/usr/bin/env python3
"""Печатная HTML-версия: браузер загружает исходные фото напрямую и встраивает их при печати в PDF."""
import json,re
from pathlib import Path
from html import escape as e
ROOT=Path(__file__).resolve().parents[1]
s=(ROOT/'index.html').read_text();a=s.index('const CATALOG = ')+len('const CATALOG = ');c=json.loads(s[a:s.index(';\nconst $=',a)])
def fmt(n):
 whole,frac=f'{n:.2f}'.split('.');return f'{int(whole):,}'.replace(',',' ')+(','+frac if frac!='00'else'')
def logo():return '<svg class="logo" viewBox="0 0 2030 440" role="img" aria-label="nash dvor — from vision to reality"><use href="#brand-lockup"/></svg>'
def foot(n,t):return f'<footer><span>NASH DVOR / {e(t)}</span><b>{n:02}</b></footer>'
def table(i):
 heads=''.join('<th>'+('Без утепл.'if t['mm']==0 else str(t['mm']))+'</th>'for t in i['thicknesses']);rows=[]
 for base in i['bases']:
  cells=[]
  for t in i['thicknesses']:
   p=i['price'].get(f"{base['id']}_{t['mm']}");cells.append('<td>'+(fmt(p)if isinstance(p,(int,float))else'—')+'</td>')
  rows.append('<tr><th scope="row">'+e(base['name'])+'</th>'+''.join(cells)+'</tr>')
 return '<table><thead><tr><th>Основа / мм</th>'+heads+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table>'
def product(i):
 name=re.sub(r'^(Керамогранітна|Клінкерна) термопанель\s*|^Термопанель під фарбування\s*|^Термопанель\s*','',i['name']).replace(' з термозамком','')
 image=('<img class="product-image" src="'+e(i['image'],quote=True)+'" alt="'+e(name,quote=True)+'" loading="eager" decoding="async">')if i.get('image')else''
 return f'<article class="product"><div class="photo"><span class="placeholder">Фото відсутнє</span>{image}</div><div class="product-details"><h3>{e(name)}</h3><div class="sku">АРТИКУЛ {e(i["sku"])}</div>{table(i)}<small>{e(i.get("status")or"")}</small></div></article>'
parts=[]
parts.append('<section class="sheet cover">'+logo()+'<div class="overline">ЦЕНТР БЛАГОУСТРОЮ</div><h1>Фасадні<br>термопанелі.</h1><p class="lead">Фактури. Основи. Товщина. Ціни.</p><div class="cover-photos">'+''.join('<img src="'+i['image']+'" alt="Фактура панелі">'for i in [c['sections'][0]['items'][0],c['sections'][1]['items'][2],c['sections'][0]['items'][10]])+'</div><div class="cover-meta"><strong>04 <small>РОЗДІЛИ</small></strong><strong>54 <small>ПАНЕЛЕЙ</small></strong><p>Інформаційний каталог<br>для вибору матеріалів фасаду.</p></div><p>nashdvor.com.ua · Біляївка, Одеська область</p>'+foot(1,'ВІД ІДЕЇ ДО ВТІЛЕННЯ')+'</section>')
toc=''.join(f'<div class="toc"><b>0{k+1}</b><div><h3>{e(sec["title"])}</h3><p>{len(sec["items"])} панелей</p></div><strong>{rng}</strong></div>'for k,(sec,rng)in enumerate(zip(c['sections'],['03—08','09—11','12—15','16—19'])))
parts.append('<section class="sheet">'+logo()+'<div class="overline">ДОВІДНИК КАТАЛОГУ</div><h2>Знайдіть свій фасад.</h2>'+toc+'<div class="guide"><h3>Як читати таблиці</h3><p>Стовпці — товщина утеплювача в мм, рядки — основа. «—» означає, що ціна відсутня або поєднання не передбачене.</p><p><b>Усі ціни наведено у гривнях (грн).</b> Керамограніт: ціни за одну панель. Польський клінкер, панелі під фарбування та імітація клінкера: ціни за м². Одиниці вказані над таблицями.</p><p>Керамограніт: площа панелі 0,564 м². Імітація клінкера: корисна площа 0,54 м².</p></div>'+foot(2,'ЗМІСТ / ОСНОВИ / ПОЗНАЧЕННЯ')+'</section>')
page=3
for n,sec in enumerate(c['sections']):
 size=[4,3,2,4][n];chunks=[sec['items'][k:k+size]for k in range(0,len(sec['items']),size)]
 for k,chunk in enumerate(chunks):
  unit='Ціни за одну панель, грн'if chunk[0]['currency']=='грн/панель'else'Ціни за 1 м², грн'
  parts.append(f'<section class="sheet"><header>{logo()}<span>ФАСАДНІ ТЕРМОПАНЕЛІ</span></header><div class="section-heading"><b>0{n+1}</b><h2>{e(sec["title"])}</h2><span>{k+1} / {len(chunks)}</span></div><p class="units">{unit}</p><div class="products" style="--rows:{size}">'+''.join(product(i)for i in chunk)+'</div>'+foot(page,sec['title'])+'</section>');page+=1
parts.append('<section class="sheet cover back">'+logo()+'<div class="overline">ЦЕНТР БЛАГОУСТРОЮ</div><h1>Від ідеї<br>до втілення.</h1><p class="lead">Допоможемо зорієнтуватися у фактурах,<br>основах та варіантах оздоблення фасаду.</p><div class="contact"><h3>ЗВ’ЯЖІТЬСЯ З НАМИ</h3><p>+38 098 578 87 87</p><p>+38 095 578 87 87</p></div><p>Біляївка, Одеська область</p><h3>nashdvor.com.ua</h3><p>catalog.nashdvor.com.ua</p>'+foot(20,'КОНТАКТИ')+'</section>')
assert page==20 and len(parts)==20
# Используем исходные встроенные PNG и нормализованные SVG-координаты из веб-каталога.
defs=s[s.index('<svg width="0"'):s.index('<header>')]
for part,url in c['brand'].items():
 if part in ['symbol','wordmark']:defs=defs.replace('data-brand-part="'+part+'"','href="'+url+'"')
css='''
:root{--accent:#f45100;--ink:#202020;--paper:#f5f1e8;--line:#dcd8d0}*{box-sizing:border-box}body{margin:0;background:#ddd;color:var(--ink);font:11px/1.5 Arial,sans-serif}button{font:inherit;cursor:pointer}.toolbar{position:sticky;top:0;z-index:10;padding:14px 20px;background:#202020;color:white;display:flex;align-items:center;gap:16px;flex-wrap:wrap}.toolbar button{min-height:44px;padding:10px 20px;border:0;border-radius:6px;background:var(--accent);font-weight:bold;color:#202020}.toolbar button:disabled{opacity:.5}.toolbar small{display:block;color:#eee}.toolbar a{color:white}.sheet{width:210mm;height:297mm;margin:10mm auto;background:white;padding:14mm;position:relative;overflow:hidden;break-after:page}.sheet:last-child{break-after:auto}.logo{display:block;width:58mm;height:auto;aspect-ratio:2030/440}.sheet>header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:5mm;height:21mm}.sheet>header>span{font-size:8px;color:#666}.section-heading{display:flex;align-items:center;gap:8mm;margin-top:6mm}.section-heading>b{font-size:26px;color:var(--accent)}.section-heading h2{font-size:24px;line-height:1.2;margin:0}.section-heading>span{margin-left:auto;color:#666;font-size:10px}.units{margin:1mm 0 5mm 18mm;color:#666;font-size:10px}.products{display:grid;grid-template-rows:repeat(var(--rows),1fr);height:196mm;gap:4mm}.product{display:grid;grid-template-columns:43mm 1fr;gap:6mm;min-height:0;border-bottom:1px solid var(--line);padding-bottom:3mm;align-items:start}.product:last-child{border-bottom:0}.photo{height:36mm;position:relative;background:var(--paper);border-radius:2mm;display:flex;align-items:center;justify-content:center;overflow:hidden}.photo img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:var(--paper)}.placeholder{color:#666;font-size:9px;padding:10px}.product-details{min-width:0}.product h3{font-size:12px;line-height:1.25;margin:0 0 2mm;min-height:5mm}.sku{font-size:8px;color:#777;margin-bottom:3mm}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:9px}thead{background:var(--paper)}th,td{padding:1.5mm .7mm;text-align:left;vertical-align:middle;border-bottom:1px solid var(--line);overflow-wrap:normal}thead th{font-size:8px}th:first-child{width:26mm;font-size:8px}td{font-weight:bold}tbody th{font-weight:normal}small{font-size:8px;color:#666}footer{position:absolute;left:14mm;right:14mm;bottom:10mm;border-top:1px solid var(--line);padding-top:3mm;display:flex;justify-content:space-between;color:#666;font-size:8px}footer b{color:var(--ink)}.cover{background:var(--paper)}.cover .logo{width:100mm;margin:4mm 0 14mm}.overline{font-size:11px;font-weight:bold;color:var(--accent);letter-spacing:1px;margin-top:12mm}h1{font-size:52px;line-height:1.15;margin:12mm 0 8mm}.lead{font-size:16px;color:#666}.cover-photos{display:grid;grid-template-columns:repeat(3,1fr);gap:3mm;margin-top:22mm;align-items:center;height:65mm}.cover-photos img{width:100%;max-height:65mm;object-fit:contain}.cover-meta{display:flex;gap:20mm;align-items:center;border-top:2px solid var(--accent);padding-top:10mm;margin-top:9mm}.cover-meta strong{font-size:30px}.cover-meta small{display:block;font-size:9px;font-weight:normal}.cover-meta p{font-size:11px;color:#666}.toc{display:flex;align-items:center;gap:10mm;padding:7mm 0;border-bottom:1px solid var(--line)}.toc>b{font-size:22px;color:var(--accent)}.toc h3{font-size:16px;margin:0}.toc p{color:#666;margin:1mm 0 0}.toc>strong{margin-left:auto}.sheet>h2{font-size:28px;margin-top:4mm}.guide{margin-top:14mm;font-size:12px}.guide h3{font-size:17px}.back .contact{margin-top:35mm;border-top:1px solid var(--line);padding-top:10mm}.contact h3{font-size:12px;color:var(--accent)}.contact p{font-size:27px;font-weight:bold;margin:4mm 0}.print-warn{color:#ffbc8b}
@page{size:A4;margin:0}@media print{body{background:white}.toolbar{display:none!important}.sheet{margin:0;box-shadow:none}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}@media screen and (max-width:820px){.toolbar{position:relative}.sheet{margin:10px 0}}
'''
js='''
const images=[...document.querySelectorAll('.product-image')],button=document.getElementById('print-button'),status=document.getElementById('photo-status');
const ready=Promise.all(images.map(image=>new Promise(resolve=>{let done=false;const finish=()=>{if(done)return;done=true;const ok=image.complete&&image.naturalWidth>0;if(!ok)image.remove();resolve(ok)};image.addEventListener('load',finish,{once:true});image.addEventListener('error',finish,{once:true});if(image.complete)finish();setTimeout(finish,30000)}))).then(results=>{const good=results.filter(Boolean).length;status.textContent=`Завантажено фото: ${good} із ${images.length}.`;status.classList.toggle('print-warn',good<images.length);button.disabled=false;document.body.dataset.photosReady='true'});
button.addEventListener('click',async()=>{await ready;window.print()});
'''
html='<!doctype html><html lang="uk"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NASH DVOR — каталог із фотографіями для друку</title><style>'+css+'</style></head><body>'+defs+'<aside class="toolbar"><button id="print-button" disabled>Зберегти PDF / Друк</button><div><span id="photo-status">Завантаження фотографій…</span><small>У вікні друку: A4, масштаб 100%, поля «Немає», фонові зображення увімкнені, колонтитули вимкнені.</small></div><a href="../">Повернутися до каталогу</a></aside>'+''.join(parts)+'<script>'+js+'</script></body></html>'
(ROOT/'print/catalog-with-photos.html').write_text(html)
print('Created print HTML: 20 sheets, 54 products, 32 embedded + 22 remote main photos, no missing-photo products; bytes',len(html.encode()))
